// Generated by @canonical/summon-component:react v0.43.0

import { createMemoryAdapter, createRouter } from "@canonical/router-core";
import { RouterProvider } from "@canonical/router-react";
import { fireEvent, render, screen, within } from "@testing-library/react";
import type { ReactElement } from "react";
import { describe, expect, it } from "vitest";
import { LENS_ROUTES } from "../../../../testing/fixtures.js";
import type { Renderer } from "../../renderers/types.js";
import RendererSwitch from "./RendererSwitch.js";

const RENDERERS: readonly Renderer<never>[] = [
  { name: "table", label: "Table", render: () => null },
  { name: "cards", label: "Cards", render: () => null },
];

/** Render `ui` under the fixtures' router at `href`. */
const renderAt = (href: string, ui: ReactElement) => {
  const router = createRouter(LENS_ROUTES, {
    adapter: createMemoryAdapter(href),
  });
  return {
    router,
    ...render(<RouterProvider router={router}>{ui}</RouterProvider>),
  };
};

describe("RendererSwitch", () => {
  it("draws nothing for fewer than two renderers", () => {
    const { container } = renderAt(
      "/catalog",
      <RendererSwitch active="table" renderers={RENDERERS.slice(0, 1)} />,
    );
    expect(container).toBeEmptyDOMElement();
  });

  it("links each renderer by an href that differs only in as and expand", () => {
    renderAt(
      "/catalog?q=cen&expand=ds%3Aa%3Ap%3Aout",
      <RendererSwitch active="table" renderers={RENDERERS} />,
    );
    const tabs = within(screen.getByRole("navigation", { name: "Show as" }));
    expect(tabs.getByRole("link", { name: "Table" })).toHaveAttribute(
      "href",
      "/catalog?q=cen",
    );
    expect(tabs.getByRole("link", { name: "Cards" })).toHaveAttribute(
      "href",
      "/catalog?q=cen&as=cards",
    );
  });

  it("marks exactly the active renderer current, in each form", () => {
    renderAt(
      "/catalog?as=cards",
      <RendererSwitch active="cards" renderers={RENDERERS} />,
    );
    const tabs = within(screen.getByRole("navigation", { name: "Show as" }));
    const menu = within(screen.getByRole("list", { name: "Show as" }));
    for (const form of [tabs, menu]) {
      const current = form
        .getAllByRole("link")
        .filter((link) => link.getAttribute("aria-current") === "page");
      expect(current.map((link) => link.textContent)).toEqual(["Cards"]);
    }
  });

  it("names the active renderer in the menu's summary", () => {
    const { container } = renderAt(
      "/catalog?as=cards",
      <RendererSwitch active="cards" renderers={RENDERERS} />,
    );
    expect(container.querySelector("summary")?.textContent).toBe("Cards");
  });

  it("marks the default current for a renderer it does not offer", () => {
    const { container } = renderAt(
      "/catalog?as=graph",
      <RendererSwitch active="graph" renderers={RENDERERS} />,
    );
    expect(container.querySelector("summary")?.textContent).toBe("Table");
  });

  it("takes its accessible name from the label when given", () => {
    renderAt(
      "/catalog",
      <RendererSwitch active="table" label="View" renderers={RENDERERS} />,
    );
    expect(screen.getByRole("navigation", { name: "View" })).toBeVisible();
  });

  it("folds the menu once a renderer is chosen", () => {
    const { container } = renderAt(
      "/catalog",
      <RendererSwitch active="table" renderers={RENDERERS} />,
    );
    const details = container.querySelector("details");
    if (details === null) throw new Error("no menu");
    fireEvent.click(screen.getByText("Table", { selector: "summary" }));
    fireEvent(details, new Event("toggle"));
    expect(details.open).toBe(true);
    fireEvent.click(
      within(screen.getByRole("list", { name: "Show as" })).getByRole("link", {
        name: "Cards",
      }),
    );
    expect(details.open).toBe(false);
  });

  it("applies custom className and passes native props through", () => {
    renderAt(
      "/catalog",
      <RendererSwitch
        active="table"
        className="custom-class"
        data-testid="switch"
        renderers={RENDERERS}
      />,
    );
    const root = screen.getByTestId("switch");
    expect(root.className).toContain("ds renderer-switch");
    expect(root.className).toContain("custom-class");
  });
});
